import math


def desired_replicas(current_replicas, current_metric, target_metric, min_replicas, max_replicas):
    raw = current_replicas * (current_metric / target_metric)
    desired = math.ceil(raw)
    return max(min_replicas, min(max_replicas, desired))


cases = [
    (10, 80, 50, 2, 20),
    (4, 30, 50, 2, 20),
    (4, 95, 50, 2, 5),
]

for current, metric, target, lo, hi in cases:
    result = desired_replicas(current, metric, target, lo, hi)
    print(f"replicas={current} cpu={metric}% target={target}% -> desired={result}")
